import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Fetch Google Sheet Data","description":"","frontmatter":{"prev":{"text":"Send Mail (Gmail)","link":"/documentation/field-types/google-service-gmail/send-mail-gmail"},"next":{"text":"Insert / Remove HTML","link":"/documentation/field-types/others/insert-remove-html"}},"headers":[],"relativePath":"documentation/field-types/google-service-sheet/fetch-google-sheet-data.md","filePath":"documentation/field-types/google-service-sheet/fetch-google-sheet-data.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/google-service-sheet/fetch-google-sheet-data.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="fetch-google-sheet-data" tabindex="-1">Fetch Google Sheet Data <a class="header-anchor" href="#fetch-google-sheet-data" aria-label="Permalink to “Fetch Google Sheet Data”">​</a></h1><p>Retrieve real-time data from cloud-hosted Google Spreadsheets using the Google Sheets API for automated form input population.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The <strong>Fetch Google Sheet Data</strong> field type queries specific cell ranges from a Google Sheet and populates retrieved values directly into form fields or variables. It provides built-in browser caching, automatic retry handling, and formatting controls for dates and numbers.</p><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>Google Service Account</strong></td><td>Dropdown</td><td>Authorized Google account with Google Sheets API access.</td><td>Yes</td></tr><tr><td><strong>Spreadsheet ID</strong></td><td>Text Input</td><td>Unique identifier string extracted from the Google Sheet URL.</td><td>Yes</td></tr><tr><td><strong>Sheet Name</strong></td><td>Text Input</td><td>Specific tab name within the spreadsheet (e.g., <code>Sheet1</code>, <code>Inventory</code>).</td><td>Yes</td></tr><tr><td><strong>Output Range</strong></td><td>Text Input</td><td>A1-notation cell coordinate or range (e.g., <code>B2</code>, <code>A2:D2</code>).</td><td>Yes</td></tr><tr><td><strong>Value Render Option</strong></td><td>Dropdown</td><td>Formats values: <code>FORMATTED_VALUE</code> (as displayed) or <code>UNFORMATTED_VALUE</code> (raw values).</td><td>No</td></tr><tr><td><strong>Date Time Render Option</strong></td><td>Dropdown</td><td>Formats dates: <code>SERIAL_NUMBER</code> or <code>FORMATTED_STRING</code>.</td><td>No</td></tr><tr><td><strong>Enable Caching</strong></td><td>Toggle Switch</td><td>Caches retrieved values locally to minimize API quota usage.</td><td>No</td></tr><tr><td><strong>Cache Duration</strong></td><td>Number Input</td><td>Lifetime of cached records in seconds.</td><td>When caching enabled</td></tr><tr><td><strong>Enable Retry</strong></td><td>Toggle Switch</td><td>Re-attempts queries if temporary network errors occur.</td><td>No</td></tr><tr><td><strong>Maximum Retries</strong></td><td>Number Input</td><td>Maximum number of retry attempts.</td><td>When retry enabled</td></tr></tbody></table><hr><h2 id="option-details" tabindex="-1">Detailed Settings Breakdown <a class="header-anchor" href="#option-details" aria-label="Permalink to “Detailed Settings Breakdown”">​</a></h2><h3 id="google-service-account" tabindex="-1">Google Service Account <a class="header-anchor" href="#google-service-account" aria-label="Permalink to “Google Service Account”">​</a></h3><p>Select the Google account registered in <a href="/documentation/services/google-service.html">Google Service</a>. The account must hold read permissions on the target sheet.</p><h3 id="locating-the-spreadsheet-id" tabindex="-1">Locating the Spreadsheet ID <a class="header-anchor" href="#locating-the-spreadsheet-id" aria-label="Permalink to “Locating the Spreadsheet ID”">​</a></h3><p>Extract the ID token directly from your browser address bar:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://docs.google.com/spreadsheets/d/1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms/edit</span></span>
<span class="line"><span>                                        └─────────────────── SPREADSHEET ID ───────────────────┘</span></span></code></pre></div><p>In this example, the Spreadsheet ID is: <code>1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms</code>.</p><h3 id="output-range-a1-notation" tabindex="-1">Output Range (A1 Notation) <a class="header-anchor" href="#output-range-a1-notation" aria-label="Permalink to “Output Range (A1 Notation)”">​</a></h3><p>Specify the cell or range to fetch:</p><ul><li><code>A2</code>: Single cell value.</li><li><code>B2:E2</code>: Multiple columns from row 2.</li><li><code>Data!C5</code>: Specific sheet and cell reference.</li></ul><h3 id="caching-for-high-performance" tabindex="-1">Caching for High Performance <a class="header-anchor" href="#caching-for-high-performance" aria-label="Permalink to “Caching for High Performance”">​</a></h3><ul><li><strong>Enable Caching</strong>: Stores retrieved cell values in browser memory for the specified <strong>Cache Duration</strong> (e.g., <code>300</code> seconds).</li><li><strong>Benefit</strong>: Greatly accelerates repetitive executions and prevents hitting Google Sheets API rate limits.</li></ul><hr><h2 id="examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Practical Examples”">​</a></h2><h3 id="example-1-fetching-single-user-record" tabindex="-1">Example 1: Fetching Single User Record <a class="header-anchor" href="#example-1-fetching-single-user-record" aria-label="Permalink to “Example 1: Fetching Single User Record”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Google Service Account: team@company.com</span></span>
<span class="line"><span>Spreadsheet ID: 1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms</span></span>
<span class="line"><span>Sheet Name: Users</span></span>
<span class="line"><span>Output Range: B2</span></span>
<span class="line"><span>Value Render Option: FORMATTED_VALUE</span></span>
<span class="line"><span>Enable Caching: ON</span></span>
<span class="line"><span>Cache Duration: 300</span></span></code></pre></div><h3 id="example-2-real-time-dynamic-price-lookup" tabindex="-1">Example 2: Real-Time Dynamic Price Lookup <a class="header-anchor" href="#example-2-real-time-dynamic-price-lookup" aria-label="Permalink to “Example 2: Real-Time Dynamic Price Lookup”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Google Service Account: finance@company.com</span></span>
<span class="line"><span>Spreadsheet ID: 1a2b3c4d5e6f7g8h9i0...</span></span>
<span class="line"><span>Sheet Name: Rates</span></span>
<span class="line"><span>Output Range: C10</span></span>
<span class="line"><span>Enable Caching: OFF</span></span>
<span class="line"><span>Enable Retry: ON</span></span>
<span class="line"><span>Maximum Retries: 3</span></span></code></pre></div><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ul><li><strong>Use Formatted Values</strong>: Choose <code>FORMATTED_VALUE</code> when you want currency symbols, commas, or custom decimal places preserved.</li><li><strong>Enable Caching for Static Tables</strong>: If data rarely updates during an automation session, set Cache Duration to <code>600</code> (10 minutes).</li><li><strong>Verify Sheet Sharing</strong>: Make sure the target Google Sheet is shared with the authorized Google Service account.</li></ul><hr><h2 id="related" tabindex="-1">Related Documentation <a class="header-anchor" href="#related" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template &amp; Google Sheets (Beta)</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/services/google-service.html">Google Service Account Setup</a></li><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-fields/field.html">Form Fields Overview</a></li></ul>`,33)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};